const body = $input.first().json.body || $input.first().json;
const text = (body.text || '').trim();
const chatId = body.chatId;

// Extract order number: #1234 or just 1234
const match = text.match(/#?(\d+)/);
const orderId = match ? match[1] : null;

if (!orderId) {
  return [{ json: { chatId, orderId: null, error: 'no_id' } }];
}

return [{ json: { chatId, orderId } }];

const order = $input.first().json;
const chatId = $('Extract Order ID').first().json.chatId;

const statusMap = {
  pending: 'في الانتظار',
  processing: 'قيد المعالجة',
  'on-hold': 'معلّق',
  completed: 'مكتمل',
  cancelled: 'ملغي',
  refunded: 'مُسترجع',
  failed: 'فشل'
};

const status = statusMap[order.status] || order.status;
const total = order.total;
const date = order.date_created?.split('T')[0] || '';
const items = (order.line_items || []).map(i=>`- ${i.name} x${i.quantity}`).join('\n');

const message = `حالة الطلب #${order.id}\n\nالحالة: ${status}\nالإجمالي: ${total} ر.س\nالتاريخ: ${date}\n\nالمنتجات:\n${items}\n\nللمساعدة: واتساب 0570131122`;

return [{ json: { chatId, message } }];

